  '出発が記録されるのを待っています': 'Waiting for the departure to be recorded',
  '到着のターンを待っています': 'Waiting for the arrival turn',
  '到着しました。封を開ける鍵が出るのを待っています（ターンが終わると出ます）。': 'Arrived. Waiting for the key that opens the seal (it comes out when the turn ends).',
  '封が開けられるのを待っています': 'Waiting for the seal to be opened',
  '衝突の結果を待っています': 'Waiting for the result of the clash',
  '結果が出ました。受け取りを待っています。': 'The result is out. Waiting for it to be collected.',
  'すべて済みました': 'All done',
  'この端末には封の控えがありません。封は、到着のターンが終わったあと自動で開けられます。': 'This device has no copy of the seal. It will be opened automatically after the arrival turn ends.',
  'チェーンに記録された封が、この端末で作った封と違います。この端末からは開けません。': 'The seal recorded on chain differs from the one this device made. This device will not open it.',
  '送りました。記録されるのを待っています。': 'Sent. Waiting for it to be recorded.',
  'この端末が封を開ける手続きを送りました': 'This device has sent the request to open the seal.',
  '封が開けられました': 'The seal has been opened.',
  '結果を受け取りました': 'The result has been collected.',
  '到着のターンが始まると、この端末が封を開けます（ウォレットの操作は要りません）。': 'When the arrival turn begins, this device opens the seal (your wallet is not needed).',
  '（封は開けられました）': '(the seal has been opened)',
  '（行き先と構えはあなたにだけ見えます）': '(only you can see the destination and the stance)',
  '封が開けられないまま、受付が終わりました。軍勢は敗走する（兵・体力・チップの半分を失う）か、同じ国の到着が多すぎたときは損失なしで村へ戻ります。': 'The time for opening seals ended with this seal still closed. The host is routed (it loses half its troops, stamina and tip) or, if too many hosts of your nation arrived, it returns home without loss.',
  '結果を受け取る': 'Collect the result',
  'ふつうは自動で受け取ります。': 'It is normally collected automatically.',
  '進軍の結果を受け取るまで、この軍勢は出発・解散・探索ができません（ふつうは自動で受け取ります）。': 'Until this march is resolved, the host cannot march, dissolve or explore (it is normally resolved automatically).',
  'ターン {0} まで休息': 'Resting until turn {0}',
  '出発の手続き中': 'Departure in progress',
  '封が正しくなかったため失われます': 'Will be lost: its seal was not valid',
  'ターン {0} に、{1}へ最大 {2} の軍勢（{3} 兵）が来るかもしれません。行き先は封印中です。': (t, v, h, n) => `On turn {0}, ${plural(h, 'up to {2} host', 'up to {2} hosts')} ({3} troops) may arrive ${atPlace(v)}. Where they are going is sealed.`,
  'ルールを読み込めていないため、来襲の恐れを調べられません。': 'The rules have not loaded, so possible attacks cannot be worked out.',
  'いまのところ、あなたの村に届きそうな他国の軍勢は出ていません。': 'For now, no host of another nation that could reach your villages has set out.',
