  '出発地': 'From',
  '出発地と行き先を選んでください': 'Choose where the caravan leaves from and where it goes',
  '出発地と行き先が同じです': 'The caravan would leave from where it goes',
  '出発地か行き先のマスがわかりません': 'The tile of the start or of the destination is not known',
  '運べる量は出発地の蔵にある分までです（出発地ごとの在庫は上の一覧のとおり）。': 'A caravan carries at most what its start holds (each start\'s stores are in the list above).',
  '在庫はまだ読み込んでいません': 'stores not read yet',
  '空': 'empty',
  '（上限 {0}）': ' (cap {0})',
  '投票と提案は、ターン {0} からできます（国に加わってから {1} ターン）。': 'Voting and proposing open at turn {0} ({1} turns after joining the nation).',
  '投票と提案は、国に加わってから {0} ターン後にできるようになります。': 'Voting and proposing open {0} turns after joining the nation.',
  '投票中の議題が {0} 件あるため、新しい提案は締め切りを待ってから出せます。': n => plural(n, '{0} proposal is open; a new one can be made once it closes.', '{0} proposals are open; a new one can be made once one closes.'),
  '賛成 {0} · 反対 {1} · 締め切り（集計を待っています）': 'Yes {0} · No {1} · closed (waiting for the tally)',
