  '{0}を奪う': 'Seize the {0}',
  '{0}を奪いました': 'Seized the {0}',
  'このマスに立つあなたの軍勢が、持ち主に代わってこの{0}を自分のものにします。持ち主の軍勢がいると奪えません。': 'Your host standing on this tile takes this {0} from its owner. It cannot while a host of the owner stands here.',
  'このマスに、着いて落ち着いたあなたの軍勢がいません（進軍で送り、次のターンを待ってください）': 'No host of yours has arrived and settled on this tile (march one here and wait for the next turn)',
  '持ち主の情報をまだ読み込んでいません。少し待ってください': 'The owner is not read yet. Wait a moment',
  'このマスには奪えるものがありません': 'Nothing on this tile can be seized',
  '自由都市を包囲する': 'Besiege the Free City',
  'この村を包囲する': 'Besiege this village',
  '包囲が続けば自由都市を取り、あなたの村になります。': 'If the siege holds, the Free City is taken and becomes your village.',
  '包囲が続けば、最初の村なら占領、ほかの村なら奪取になります。': 'If the siege holds, a first village is occupied and any other village is captured.',
  '宣言には軍勢の村から金 {0}（包囲の結果で返るか失われます）と兵器 {1} を使います。宣言は公開され、守り手に知らされます。': 'Declaring uses {0} gold (returned or lost as the siege ends) and {1} arms from the host\'s village. The declaration is public and the defender is told.',
  '包囲を宣言する': 'Declare the siege',
  'この村のマスに、着いて落ち着いたあなたの戦う軍勢（斥候以外）がいません。進軍で送り、守りに勝ってから包囲を宣言します': 'No fighting host of yours (not a scout) has arrived and settled on this village\'s tile. March one here, win against its defence, then declare the siege',
  'このマスには包囲できる村がありません': 'There is no village to besiege on this tile',
  '村の持ち主を確かめています…': 'Checking the village\'s owner…',
  '村（占領）': 'village (occupation)',
  '村（奪取）': 'village (capture)',
  '{0}の包囲を宣言しました': 'Declared the siege of the {0}',
  '工房が鉱石をすべて使っていて、鉱石が増えていません。兵の訓練にも鉱石が要るので、鉱山を建てるまで訓練できなくなります。': 'The workshops use all the ore and the ore does not grow. Training needs ore too, so troops cannot be trained until a mine is built.',
  '国の議会に提案する': 'Propose to the nation\'s council',
  'この村は同じ国の村です。国から追放する提案を出すと、国の村が1日のあいだ投票します。追放された村は、国の村の柵に止められるようになり、投票も提案もできなくなります。': 'This village is of your own nation. A proposal to expel it is voted on by the nation\'s villages for one day. An expelled village is stopped by the nation\'s palisades and can neither vote nor propose.',
  'この村の追放を提案する': 'Propose to expel this village',
