  '第{0}〜{1}ターンの記録 {2} 件を読みました。': (a, b, n) => plural(n, 'Read {2} record of turns {0}–{1}.', 'Read {2} records of turns {0}–{1}.'),
  '新しい記録はありません。': 'No new records.',
  '新しい記録があるかどうかは、まだわかりません。': 'Whether there are new records is not known yet.',
  '中身を読めた新しい記録はありません。': 'No new records whose contents could be read.',
  'あなたが確認したのは第{0}ターンまでです。': 'You marked up to turn {0} as seen.',
  'この端末では、この世界とウォレットで確認した記録がありません（初めてか、別の端末か、ブラウザの記録が消えた場合）。直近 {0} ターンだけを見ています。': 'This device holds no "seen" mark for this world and wallet (a first visit, another device, or cleared browser data). Only the last {0} turns are shown.',
  'この端末で前に使ったウォレット（または住民NFT）とは別です。その記録は使いません。直近 {0} ターンだけを見ています。': 'This is not the wallet (or resident NFT) last used on this device; its record is not used. Only the last {0} turns are looked at.',
  '前に見ていたものとは別の記録（ID が違う記録）です。前の記録の出来事は、ここには含めていません。': 'This is another record (a different ID) from the one seen before. Events of that record are not included here.',
  '確認した位置のあとの記録の一部を読めていません。欠けた分の出来事は推測しません。': 'Some records after your mark could not be read; nothing is guessed for them.',
  'この端末に残っていた確認の位置は、いまの世界の記録より先を指していたため使いません。直近 {0} ターンだけを見ています。': 'The mark kept on this device points past this world\'s records, so it is not used. Only the last {0} turns are shown.',
  'この端末では第{0}ターンより前の出来事は見ていません。': 'Nothing before turn {0} was seen on this device.',
  '読めたのは第{0}ターンからです。': 'Records could be read from turn {0} only.',
  '記録の読み込みが途中で失敗しました。読めた分だけを出しています。': 'Reading the records failed part way; only what was read is shown.',
  '記録はまだ続きがあります。読めた分だけを出しています。': 'There are more records still; only what was read is shown.',
  '記録の読み込みに失敗しました。': 'Reading the records failed.',
  '記録はまだ続きがあります。': 'There are more records still.',
  '読めない記録が {0} 件ありました。その中身は推測しません。': n => plural(n, '{0} record could not be read; what is in it is not guessed.', '{0} records could not be read; what is in them is not guessed.'),
  '欠けた記録を読めるまで、確認の位置は進めません（× で閉じても位置は動きません）': 'Your mark stays where it is until the missing records can be read (closing with × does not move it)',
  '新しく確認する記録はありません': 'Nothing new to mark as seen',
  'まだ記録を読めていないため、確認の位置は進めません': 'No records have been read yet, so the seen mark does not move',
  '読めない記録のほかに、新しく確認する記録はありません': 'Apart from the records that could not be read, nothing new to mark as seen',
  '確認すると、読めた第{0}ターンまでを確認済みにします（その先は次に読みます）': '"Seen" marks up to turn {0}, as far as was read (the rest is read next time)',
  '確認すると、第{0}ターンまでを確認済みにします': '"Seen" marks up to turn {0}',
  '確認の位置を保存できませんでした。次に開いたときも同じ範囲が出ます': 'Your mark could not be saved. The same records will be shown next time',
  '第{0}ターンまでを確認済みにしました': 'Marked as seen up to turn {0}',
  '第{0}ターンまでを確認済みにしました（この端末で最後に使ったウォレットの記録だけは保存できませんでした）': 'Marked as seen up to turn {0} (only this device\'s note of the wallet used last could not be saved)',
  'この端末ではすでに第{0}ターンまで確認済みです': 'This device already has turns up to {0} marked as seen',
  'あなたが送った隊商が略奪され、積荷は焼かれました（ターン {0}）。その前に別の誰かに奪われていたかは、読み込んだ記録からはわかりません{1}': 'A caravan you sent was raided and its cargo burned (turn {0}). Whether someone had taken it before is not in the records read{1}',
  'あなたが送った隊商が奪われました（ターン {0}）。その前に別の誰かに奪われていたかは、読み込んだ記録からはわかりません{1}': 'A caravan you sent was taken (turn {0}). Whether someone had taken it before is not in the records read{1}',
  'あなたが送った隊商が襲われました（ターン {0}）。いまの持ち主があなたかどうかは、読み込んだ記録からはわかりません': 'A caravan you sent was caught (turn {0}). Whether it is still yours is not in the records read',
  'あなたが送った隊商の到着が記録されました（ターン {0}）。途中で奪われていたなら、受け取ったのは奪った側です（読み込んだ記録からは確かめられません）{1}': 'The arrival of a caravan you sent was logged (turn {0}). If it had been taken on the way, the taker received it (the records read cannot tell){1}',
  'あなたが送った隊商の行き先がなくなり、積荷が失われたと記録されました（ターン {0}）。途中で奪われていたなら、失ったのは奪った側です（読み込んだ記録からは確かめられません）{1}': 'A caravan you sent was logged as lost, its destination gone (turn {0}). If it had been taken on the way, the loss was the taker\'s (the records read cannot confirm it){1}',
  'あなたが送った隊商の決着が記録されました（ターン {0}）。結果を記録から読めないため、着いたとも失われたとも言いません{1}': 'The end of a journey of a caravan you sent was logged (turn {0}). Its result cannot be read from the record, so it is not said to have arrived or to be lost{1}',
  'あなたの村がまだ保護期間中です。保護が終わるまで、ほかの村を包囲できません': 'Your village is still under its shield. You cannot besiege another until it ends',
  'この村ではすでに包囲か占領が進んでいます': 'A siege or an occupation of this village is already under way',
  '前の包囲の賭け金の行き先がまだ決まっていません': 'Where the stake of the last siege here goes is not decided yet',
  '宣言したあとにプログラムが判定すること：占領後の免除、先頭の軍勢、遅れて置かれた村の保護、奪う枠の空き、この世界の受付の終わりまでに終わるか。': 'Judged by the program after you declare: immunity after a capture, the lead host, a late village\'s protection, a free capture slot, and whether it can end before this world stops taking orders.',
  '道の途中で戦争中の国の物見櫓の見張りの中を歩くため、着く前に兵が {0} → {1}（{2}%）に減ります。': 'The road walks inside the watch of towers of a nation at war: the host is worn from {0} to {1} ({2}%) before it arrives.',
  '砦・要塞の守備兵と物見櫓の減りは、いま立っているもので数えています。': 'Keep and fort garrisons and tower wear are counted as they stand now.',
  'この道は通れません': 'This road is closed',
  '戦争中の国の柵が道にあります。封が開くときに進軍は認められません': 'A palisade of a nation at war stands on the road. The march would be refused when its seal opens',
  '決める期限を過ぎました。': 'The time to decide has passed. ',
