  '決着中': 'Resolving',
  '保管庫から読んでいます': 'Read from the archive',
  'ターンのしくみ': 'How a turn works',
  '進軍は、到着のターンが始まる前に封をして送ります。守り手は、ターンの始まりにそこにいた軍勢で決まります。ターンが終わると封を開ける鍵（公開の乱数）が出て、誰でも封を開けられるようになります。封を開ける受付は決まった時間で終わり、そのあとに出る公開の乱数で衝突が決まります。': 'A march is sealed and sent before its arrival turn begins. The defenders are the hosts that were there when the turn began. When the turn ends, the key that opens its seals comes out (public randomness) and anyone can open them. Seals can be opened for a set time, and the public randomness that comes out after that decides the clashes.',
  '村の申し込みの預け金（いま要る額）': 'Village request deposit (needed now)',
  '（クラスターが答えた家賃で計算）': '(at the rent the cluster stated)',
  '（クラスターの家賃 {0} ランポート/バイトで計算）': '(at the cluster\'s rent of {0} lamports per byte)',
  '（目安：家賃をクラスターから読めていないため、{0} ランポート/バイトと仮定した額です）': '(an estimate: the cluster\'s rent could not be read, so this assumes {0} lamports per byte)',
  '封を開ける、衝突を決着させる、結果を届ける。こうした手続きは、ターンごとに自動の係（キーパー）が代わりに行います。チップはその報酬です。': 'Opening the seals, resolving the clashes, delivering the results: automatic services (keepers) do these for you every turn. The tip is their reward.',
  'いまの段階に賞金はありません。費用はテスト用の SOL で、ゲーム側（中継サーバー）が立て替えます（価値はありません）。': 'There are no prizes at this stage. Costs are in test SOL, covered by the game\'s relay (it has no value).',
  '封の保証金（結果を受け取ると戻る）': 'Seal bond (returned when the result is collected)',
