  '参加費と賞金プール（テストUSDC）': 'Entry fee and prize pool (test USDC)',
  '参加費は {0} テストUSDC です。ウォレットが署名する1つの取引で、参加費の支払いと参加が同時に行われます（x402）。': 'The entry fee is {0} test USDC. One transaction signed by your wallet pays the fee and joins at once (x402).',
