  'テストUSDCを受け取る': 'Get test USDC',
  '足りない場合は、参加の前に自動で受け取ります。': 'If the wallet is short, it is topped up automatically before joining.',
  'テストUSDCはこのローカルのテスト用チェーンだけの通貨で、価値はありません。この賞金プールは、このテスト用の世界が時間の上限（ローカルの試験だけの上限）に来たときに1回だけ集計されます。そのとき最も多くの州を持つ国が勝ち、賞金プールはその国の参加費を払ったメンバーに分けられます。': 'Test USDC exists on this local test chain only and has no value. This prize pool is counted once, when this test world reaches its time limit (a limit of local tests only). The nation holding the most provinces then wins, and the pool is shared among its members who paid the entry fee.',
