  '{0} のいる州が、ターンの処理を進めています。処理が済むと、このターン（ターン {1}）から出発できます。': '{0}: the province is still working through the turn change. This host can depart from this turn (turn {1}) as soon as it has caught up.',
  '{0} は休息中です。ターン {1} から出発できます。': '{0}: resting. This host can depart from turn {1}.',
  '{0} は体力が足りません（{1}/{2}）。ターン {3} から出発できます。': '{0}: short of stamina ({1}/{2}). This host can depart from turn {3}.',
  '{0} は進軍に出ています。結果を受け取ると、また出発できます。': '{0}: on the march. This host can depart again once its result is collected.',
  // fix-loop7, LP7-6
  '{0} の進軍は到着のターン {1} を過ぎ、結果が出ています。村の記録で進軍の締めくくり（決着の反映）が済むと、また出発できます。このページが自動で読み直します。': '{0}: the march is past its arrival turn {1} and its result is out. This host can depart again once the village record closes the march (the result is applied). This page reads it again automatically.',
