  '砦のマスを {0} ターン（{1}）続けて保つと、その州はあなたの国のものになります。行を選ぶと命令の紙が開きます（封をするまで何も送られません）。': 'Hold a keep\'s tile for {0} consecutive turns ({1}) and the province becomes your nation\'s. Choosing a row opens the order; nothing is sent until you seal it.',
  '支配する州：{0}': 'Provinces held: {0}', '{0}（押すと順位の表を開きます）': '{0} (press to open the standings)',
  '第{0}ターンまでのチェーンの記録です。押すと順位の表を開きます': 'From the chain\'s records up to turn {0}. Press to open the standings',
  '最終の州の数': 'Final provinces',
