  // ---- the guide on a conquest season (screens/conquestguide.mjs): seven steps from the first village to a province taken
  '建物を建てる': 'Build', '砦へ進軍する': 'March on a keep', '砦のマスを {0} ターン保つ': 'Hold the keep\'s tile for {0} turns', '州を奪う': 'Take the province',
  '国を選ぶと、最初の村が自動で置かれます。': 'Choose a nation and your first village is placed for you.',
  '村を選び、「建てる」から最初の建物を選びます。建物は毎時の産出を増やします。': 'Select your village and choose a first building under "Build". A building raises what the village produces each hour.',
  '「訓練」で兵を雇います。訓練はすぐに終わり、兵は村の控えに入ります。{0}': 'Hire troops under "Train". Training is instant and the troops join the village\'s reserve. {0}',
  '「編成」で控えの兵を軍勢にします。軍勢は、記録に現れたターンから動かせます。{0}': 'Under "Form a host", gather the reserve into a host. A host can be ordered from the turn it stands in the record. {0}',
  '砦を攻めるなら、{0} 以上を一つの軍勢にまとめると、守備兵 {1} の砦に着いたターンに勝てる見込みです。': 'To attack a keep, gather {0} or more into one host: that should win the arrival turn at a keep of {1} defenders.',
  '{0}軍勢を選び、「砦へ進軍」で届く他国の砦を選びます。勝ち目の欄が「十分」の砦を選ぶと、着いたターンに砦のマスに残れる見込みです。命令に封をして出発すると、到着のターンに戦いが決まります。': '{0}Select a host and choose a keep of another nation under "March on a keep". A keep whose odds read "Good" should be held on the arrival turn. Seal the order and depart: the clash is decided on the arrival turn.',
  '{0}軍勢を選び、「砦へ進軍」で届く他国の砦を選びます。': '{0}Select a host and choose a keep of another nation under "March on a keep".',
  '前の進軍は{0}の砦のマスに残れず、村へ押し戻されました。': 'Your last march could not stay on the tile of the keep at {0} and was pushed back to the village. ',
  '{0}いまの軍勢（{1}）で届く砦（守備兵 {2}、城壁あり）を攻めると、{3}{4}訓練で兵を足し、今の軍勢を解散して控えに戻してから（次のターンに戻ります）、まとめて編成し直します。': '{0}If your host as it stands ({1}) attacks a keep in reach ({2} defenders, behind walls), {3}{4}Train more troops, dissolve this host back into the reserve (its troops are back next turn), then form one host of them all.',
  '勝ち目は五分です。': 'the odds are even. ', '勝ち目は低いです。': 'the odds are poor. ',
  '{0} ほどにしてから進軍すると、運が悪くても砦のマスに残れます。': 'With about {0} it should hold the tile even with bad luck. ',
  '兵を足す': 'Add troops',
  '届く砦を見る': 'See the keeps in reach', '進軍を見る': 'See the marches',
  '{0}の砦のマスを、あなたの国が {1} / {2} ターン保っています。{3} ターン（{4}）続けて保つと、州はあなたの国のものになります。': 'Your nation has held the tile of the keep at {0} for {1} / {2} turns. Hold it for {3} consecutive turns ({4}) and the province becomes your nation\'s.',
  '進軍が砦のマスに着いて勝つと、占拠のターンが数えられます。{0} ターン（{1}）続けて保つと、州はあなたの国のものになります。': 'Once your march arrives on the keep\'s tile and wins, the turns it holds the tile are counted. Hold it for {0} consecutive turns ({1}) and the province becomes your nation\'s.',
