  // the land preview, the selected tile (hud/inspect.mjs over frontier/land.mjs landTileLines)
  'どの国の土地でもない空き地（耕地の試験）': 'Open ground, no nation\'s land (fields trial)',
  'あなたの国の村の土地（耕地の試験）': 'Village land of your nation (fields trial)',
